using System;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Animation;
public sealed class LaunchSurface:Grid {
 public LaunchSurface(string iconId,string theme){var a=NativeWindowTheme.Current(theme);Background=new SolidColorBrush(NativeWindowTheme.ColorValue(a.colors["background"]));var fg=new SolidColorBrush(NativeWindowTheme.ColorValue(a.colors["foreground"]));var muted=new SolidColorBrush(NativeWindowTheme.ColorValue(a.colors["muted"]));var panel=new StackPanel{HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(0,0,0,30)};var identity=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Center};identity.Children.Add(new Image{Source=BrandIcons.Window(iconId),Width=56,Height=56,Margin=new Thickness(0,0,16,0)});identity.Children.Add(new TextBlock{Text="AsterHub",FontFamily=new FontFamily(new Uri(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"resources/fonts/")+System.IO.Path.DirectorySeparatorChar),"./#Inter"),FontSize=28,FontWeight=FontWeights.SemiBold,Foreground=fg,VerticalAlignment=VerticalAlignment.Center});panel.Children.Add(identity);var dots=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Center,Margin=new Thickness(0,27,0,0)};for(int i=0;i<3;i++){var dot=new Border{Width=5,Height=5,CornerRadius=new CornerRadius(3),Background=muted,Opacity=.28,Margin=new Thickness(4,0,4,0)};dots.Children.Add(dot);if(SystemParameters.ClientAreaAnimation){dot.BeginAnimation(UIElement.OpacityProperty,new DoubleAnimation(.28,.85,TimeSpan.FromMilliseconds(650)){BeginTime=TimeSpan.FromMilliseconds(i*130),AutoReverse=true,RepeatBehavior=RepeatBehavior.Forever,EasingFunction=new SineEase{EasingMode=EasingMode.EaseInOut}});}}panel.Children.Add(dots);Children.Add(panel);System.Windows.Automation.AutomationProperties.SetName(this,"AsterHub loading");}
}
